package check

import (
	"slices"
	"strings"
	"sync"

	"ergo.local/prototype/internal/sketch/syntax"
)

// MapperCache stores content-addressed MappedErgo payloads by sound check-time
// cache keys without leaking compiler-internal state into the contract.
type MapperCache interface {
	Get(key string) (string, bool)
	Keep(key, text string)
}

// SpanEntry records a verified SourceSpanMap mapping from a generated byte range
// to an asset or companion byte range.
type SpanEntry struct {
	GenStart      uint32 `json:"gen_start"`
	GenEnd        uint32 `json:"gen_end"`
	HasCompanion  bool   `json:"has_companion,omitempty"`
	Companion     uint32 `json:"companion,omitempty"`
	CompanionPath string `json:"companion_path,omitempty"`
	SrcStart      uint32 `json:"src_start"`
	SrcEnd        uint32 `json:"src_end"`
	Label         string `json:"label,omitempty"`
}

// MapperDiagRecord records a structured diagnostic reported by a content mapper.
type MapperDiagRecord struct {
	Warning       bool   `json:"warning,omitempty"`
	HasCompanion  bool   `json:"has_companion,omitempty"`
	Companion     uint32 `json:"companion,omitempty"`
	CompanionPath string `json:"companion_path,omitempty"`
	SrcStart      uint32 `json:"src_start"`
	SrcEnd        uint32 `json:"src_end"`
	Code          string `json:"code,omitempty"`
	Message       string `json:"message"`
	Hint          string `json:"hint,omitempty"`
	MappedFile    string `json:"mapped_file,omitempty"`
	MappedLine    uint32 `json:"mapped_line,omitempty"`
	MappedCol     uint32 `json:"mapped_col,omitempty"`
}

// MapperRecord captures one check-time content mapper execution for inspection
// and replay provenance.
type MapperRecord struct {
	Target     string             `json:"target"`
	Kind       string             `json:"kind"`
	AssetPath  string             `json:"asset_path,omitempty"`
	FileName   string             `json:"file_name,omitempty"`
	Line       uint32             `json:"line,omitempty"`
	Col        uint32             `json:"col,omitempty"`
	MapperPkg  string             `json:"mapper_pkg,omitempty"`
	MapperFunc string             `json:"mapper_func,omitempty"`
	MediaKind  string             `json:"media_kind,omitempty"`
	CacheKey   string             `json:"cache_key,omitempty"`
	CacheHit   bool               `json:"cache_hit,omitempty"`
	Steps      int64              `json:"steps,omitempty"`
	BytesUsed  int64              `json:"bytes_used,omitempty"`
	Generated  string             `json:"generated,omitempty"`
	Decls      []string           `json:"decls,omitempty"`
	Spans      []SpanEntry        `json:"spans,omitempty"`
	Diags      []MapperDiagRecord `json:"diags,omitempty"`
}

// DeriveRecord holds the content mapper state resolved for a checked package.
type DeriveRecord struct {
	Records      []MapperRecord
	RefusedNames map[string]bool
	RefusedRoots map[string]bool
}

// Empty reports whether d recorded no content mapper expansion or refusal.
func (d *DeriveRecord) Empty() bool {
	return d == nil || (len(d.Records) == 0 && len(d.RefusedNames) == 0 && len(d.RefusedRoots) == 0)
}

// Record returns the MapperRecord for target when present.
func (d *DeriveRecord) Record(target string) (MapperRecord, bool) {
	if d == nil {
		return MapperRecord{}, false
	}
	for _, r := range d.Records {
		if r.Target == target {
			return r, true
		}
	}
	return MapperRecord{}, false
}

// DeriveExpandRequest carries the package AST files and check context passed to
// the content-mapper expander before type collection runs.
type DeriveExpandRequest struct {
	PkgPath  string
	Files    []*syntax.File
	Importer Importer
	Cache    MapperCache
	BuildID  string
}

// DeriveExpandResult returns synthesized in-memory Ergo files, replaced shell
// TypeDecls, inspection records, diagnostics, and diagnostic remapping.
type DeriveExpandResult struct {
	GeneratedFiles []*syntax.File
	ReplacedDecls  map[*syntax.TypeDecl]bool
	FileOrigins    map[*syntax.File]int
	Record         *DeriveRecord
	Diags          []Diagnostic
	RemapDiag      func(file *syntax.File, d Diagnostic) (origFile int, mapped Diagnostic, ok bool)
}

type deriveExpanderState struct {
	mu       sync.RWMutex
	expander func(DeriveExpandRequest) DeriveExpandResult
}

var registeredDeriveExpander deriveExpanderState

// RegisterDeriveExpander registers the content-mapper expander (internal/sketch/contentmap)
// used for non-Provider `type T derive E` clauses without introducing a dependency cycle
// or syntax.Parse calls inside package check.
func RegisterDeriveExpander(fn func(DeriveExpandRequest) DeriveExpandResult) {
	registeredDeriveExpander.mu.Lock()
	defer registeredDeriveExpander.mu.Unlock()
	registeredDeriveExpander.expander = fn
}

func currentDeriveExpander() func(DeriveExpandRequest) DeriveExpandResult {
	registeredDeriveExpander.mu.RLock()
	defer registeredDeriveExpander.mu.RUnlock()
	return registeredDeriveExpander.expander
}

func isContentMapperDerive(td *syntax.TypeDecl) bool {
	return td != nil && td.Derive != nil && td.TypeParams == nil && !syntax.IsProviderPlan(td.Derive)
}

func hasNonProviderDerives(files []*syntax.File) bool {
	for _, f := range files {
		for _, d := range f.Decls {
			if td, ok := d.(*syntax.TypeDecl); ok && isContentMapperDerive(td) {
				return true
			}
		}
	}
	return false
}

func expandDerives(path string, files []*syntax.File, imp Importer, opts Options) DeriveExpandResult {
	if !hasNonProviderDerives(files) {
		return DeriveExpandResult{}
	}
	fn := currentDeriveExpander()
	if fn == nil {
		var diags []Diagnostic
		refused := map[string]bool{}
		for fi, f := range files {
			for _, d := range f.Decls {
				td, ok := d.(*syntax.TypeDecl)
				if !ok || !isContentMapperDerive(td) {
					continue
				}
				line, col := f.Position(td.Derive.Pos())
				diags = append(diags, Diagnostic{
					Code:    CodeType,
					Message: "content mapper expander is not registered",
					File:    fi,
					Offset:  int(td.Derive.Pos()),
					Length:  int(td.Derive.End() - td.Derive.Pos()),
					Line:    line,
					Column:  col,
				})
				if td.Name != nil {
					refused[td.Name.Name] = true
				}
			}
		}
		return DeriveExpandResult{
			Record: &DeriveRecord{RefusedNames: refused, RefusedRoots: refused},
			Diags:  diags,
		}
	}
	return fn(DeriveExpandRequest{
		PkgPath:  path,
		Files:    files,
		Importer: imp,
		Cache:    opts.MapperCache,
		BuildID:  opts.MapperBuildID,
	})
}

func isGeneratedFile(f *syntax.File, res DeriveExpandResult) bool {
	if f == nil || res.FileOrigins == nil {
		return false
	}
	_, ok := res.FileOrigins[f]
	return ok
}

func usesImportInDerive(file *syntax.File, importName string) bool {
	if file == nil || importName == "" {
		return false
	}
	used := false
	for _, d := range file.Decls {
		td, ok := d.(*syntax.TypeDecl)
		if !ok || td.Derive == nil || syntax.IsProviderPlan(td.Derive) {
			continue
		}
		syntax.Inspect(td.Derive, func(n syntax.Node) bool {
			if used {
				return false
			}
			switch x := n.(type) {
			case *syntax.SelectorExpr:
				if id, ok := x.X.(*syntax.Ident); ok && id.Name == importName {
					used = true
					return false
				}
			case *syntax.Ident:
				if x.Name == importName {
					used = true
					return false
				}
			}
			return true
		})
	}
	return used
}

func isRefusedDerivedName(rec *DeriveRecord, name string) bool {
	if rec == nil || name == "" {
		return false
	}
	if rec.RefusedNames[name] {
		return true
	}
	for root := range rec.RefusedRoots {
		if name == root {
			return true
		}
		if len(name) > len(root) && strings.HasSuffix(name, root) {
			return true
		}
	}
	return false
}

func cloneFileList(files []*syntax.File, extra []*syntax.File) []*syntax.File {
	out := make([]*syntax.File, 0, len(files)+len(extra))
	out = append(out, files...)
	out = append(out, extra...)
	return slices.Clone(out)
}
